var i=`0314-stocafi`;var n=`world-0314`;var o=`MC`;var a=`western-europe`;var r=4;var s=1474;var l={en:`Stocafi`,ua:`Стокафі`};var d={en:`A traditional Monaco dish made with salt cod, yellow onion, garlic, tomato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Монако. Основні інгредієнти: солона тріска, жовта цибуля, часник, помідор. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Desalt the salt cod in the refrigerator for 24–48 hours, changing the water several times, then drain and cut into portions.`,ua:`Вимочіть солону тріску в холодильнику протягом 24–48 годин, кілька разів змінюючи воду; злийте її й порціонуйте рибу.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,650,`g`],[`water`,1500,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,55,`ml`],[`tomato`,290,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`black-olives`,95,`g`],[`dry-white-wine`,160,`ml`],[`parsley`,18,`g`]]}];var u={slug:i,id:n,country:`MC`,region:a,servings:4,minutes:s,title:l,text:d,steps:g};export{o as country,u as default,n as id,s as minutes,a as region,r as servings,i as slug,g as steps,d as text,l as title};